        require(duration_ > 0, "dur0");

        c.requestLoan(amount_, interest_, loanToCollateral_, duration_);
        uint256 reqID = 0;
        uint256 loanID = c.clearRequest(reqID, repayDirect_, isCallback_);

        C.Loan memory loanBefore = c.getLoan(loanID);
        require(loanBefore.lender == address(this), "lender");

        bool reverted;
        try c.claimDefaulted(loanID) { reverted = false; } catch { reverted = true; }

        if (block.timestamp <= loanBefore.expiry) {
            assert(reverted);
        } else {
            assert(!reverted);
        }
    }

    receive() external payable {}
}

