contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address owner_,
        address collateral_,
        address debt_,
        address factory_,
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_
    ) public {
        require(collateral_ != address(0), "invalid collateral");
        require(loanToCollateral_ != 0, "zero loanToCollateral");

        address ownerBefore = c.owner();
        address collateralBefore = address(c.collateral());
        address debtBefore = address(c.debt());
        address factoryBefore = address(c.factory());

        uint256 beforeLen = c.requests.length;

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        (uint256 gotAmount, uint256 gotInterest, uint256 gotLoanToCollateral, uint256 gotDuration, bool active) = c.requests(reqID);

        assert(
            ownerBefore == c.owner() &&
            collateralBefore == address(c.collateral()) &&
            debtBefore == address(c.debt()) &&
            factoryBefore == address(c.factory()) &&
            reqID == beforeLen &&
            beforeLen + 1 == c.requests.length &&
            gotAmount == amount_ &&
            gotInterest == interest_ &&
            gotLoanToCollateral == loanToCollateral_ &&
            gotDuration == duration_ &&
            active
        );
    }
}

